    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit() or s[i] == '.':
                start = i
                dots = 0
                while i < len(s) and (s[i].isdigit() or s[i] == '.'):
                    if s[i] == '.':
                        dots += 1
                    i += 1
                num_str = s[start:i]
                if dots > 1 or num_str == '.':
                    raise ValueError(f"Malformed number: {num_str}")
                tokens.append(('NUM', float(num_str) if '.' in num_str else int(num_str)))
            elif s[i:i+2] == '**':
                tokens.append(('OP', '**'))
                i += 2
            elif s[i:i+2] == '//':
                tokens.append(('OP', '//'))
                i += 2
            elif s[i] in '+-*/%()':
                tokens.append(('OP', s[i]))
                i += 1
            else:
                raise ValueError(f"Unknown character: {s[i]}")
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def consume(self):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of expression")
            self.pos += 1
            return token

        def parse_expr(self):
            node = self.parse_term()
            while self.peek() and self.peek()[1] in ('+', '-'):
                op = self.consume()[1]
                right = self.parse_term()
                node = node + right if op == '+' else node - right
            return node

