def invoice_total(items, coupon=None, member=False):
    """
    Calculates the invoice total with member discounts, specific coupons,
    and a bulk discount for large orders.
    """
    total = 0
    food_subtotal = 0
    total_qty = 0

    # Calculate base totals and quantities in a single pass
    for item in items:
        qty = item["qty"]
        if qty > 0:
            price_qty = item["price"] * qty
            total_qty += qty

            if item["category"] == "food":
                total += price_qty
                food_subtotal += price_qty
            else:
                # Apply 5% member discount on non-food items
                total += price_qty * 0.95 if member else price_qty

    # Apply coupon discounts
    if coupon is not None:
        if coupon == "SAVE5":
            if total >= 50:
                total -= 5
        elif coupon == "HALFFOOD":
            total -= food_subtotal / 2
        elif coupon == "BULK10":
            # 10% off total if total quantity of items (qty > 0) is at least 10
            if total_qty >= 10:
                total *= 0.9
        else:
            raise ValueError("unknown coupon")

    # Ensure total is not negative and round to 2 decimal places
    return round(max(0, total), 2)
