def parse_csv_line(line: str) -> list[str]:
    if not line:
        return [""]

    fields = []
    i, n = 0, len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field logic
            val = []
            i += 1  # Skip the opening double quote
            found_end = False

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Double double-quote represents a single literal double quote
                        val.append('"')
                        i += 2
                    else:
                        # Closing quote found
                        found_end = True
                        i += 1
                        break
                else:
                    val.append(line[i])
                    i += 1

            if not found_end:
                raise ValueError("Unclosed quoted field")

            # After the closing quote, the next character must be a comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Text found after closing quote")

            fields.append("".join(val))

            # If the quote was followed by a comma, move index past it
            if i < n and line[i] == ',':
                i += 1
                # If the comma was the last character, add a trailing empty field
                if i == n:
                    fields.append("")
        else:
            # Unquoted field logic
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

            if i < n and line[i] == ',':
                i += 1
                # If the comma was the last character, add a trailing empty field
                if i == n:
                    fields.append("")

    return fields
