def expand_ranges(s: str) -> list[int]:
    """
    Parses a comma-separated string of integers and ranges into a sorted list
    of unique integers.
    """
    if not s.strip():
        return []

    res = set()
    for part in s.split(','):
        item = part.strip()
        if not item:
            raise ValueError("Empty item")
        if ' ' in item:
            raise ValueError("Space inside number")

        # Case 1: Single integer
        try:
            res.add(int(item))
            continue
        except ValueError:
            pass

        # Case 2: Range a-b
        found_range = False
        for i in range(1, len(item)):
            if item[i] == '-':
                try:
                    a = int(item[:i])
                    b = int(item[i+1:])
                    if a > b:
                        raise ValueError("Range start must be <= end")
                    for n in range(a, b + 1):
                        res.add(n)
                    found_range = True
                    break
                except ValueError:
                    continue

        if not found_range:
            raise ValueError("Malformed item")

    return sorted(res)

def compress_ranges(nums) -> str:
    """
    Compresses an iterable of integers into a string with ranges for
    consecutive runs of 3 or more.
    """
    # Sort and remove duplicates
    nums = sorted(set(nums))
    if not nums:
        return ""

    # Identify consecutive groups
    groups = []
    if nums:
        current_group = [nums[0]]
        for i in range(1, len(nums)):
            if nums[i] == nums[i-1] + 1:
                current_group.append(nums[i])
            else:
                groups.append(current_group)
                current_group = [nums[i]]
        groups.append(current_group)

    # Format groups
    parts = []
    for g in groups:
        if len(g) >= 3:
            parts.append(f"{g[0]}-{g[-1]}")
        else:
            for val in g:
                parts.append(str(val))

    return ",".join(parts)
