import heapq
from collections import defaultdict

def cheapest_route(flights, src, dst, max_stops):
    """
    Finds the cheapest route from src to dst with at most max_stops intermediate airports.
    Tie-breaker order: 1. Minimum price, 2. Minimum flights, 3. Lexicographically smallest airport list.
    """
    if src == dst:
        return (0, [src])

    # Pre-process flights: keep only the cheapest flight between any two airports
    # This is safe because multiple flights between the same pair only differ in price.
    # Higher price/same steps/same path is always strictly worse.
    best_flights = {}
    for u, v, p in flights:
        if (u, v) not in best_flights or p < best_flights[(u, v)]:
            best_flights[(u, v)] = p

    adj = defaultdict(list)
    for (u, v), p in best_flights.items():
        adj[u].append((v, p))

    # Priority Queue stores tuples of (cost, steps, current_airport, path_tuple)
    # Python's heapq is a min-heap. For tie-breaking:
    # 1. cost (primary)
    # 2. steps (secondary)
    # 3. path_tuple (tertiary, lexicographical)
    # current_airport is included in the tuple to ensure consistent ordering, 
    # though it doesn't affect the logic since (cost, steps) determines the best.
    pq = [(0, 0, src, (src,))]

    # visited[(u, steps)] ensures we don't process the same (airport, number of flights)
    # state more than once. Dijkstra's ensures the first pop for (u, steps) is the best.
    visited = set()

    while pq:
        cost, steps, u, path = heapq.heappop(pq)

        if u == dst:
            return (cost, list(path))

        if (u, steps) in visited:
            continue
        visited.add((u, steps))

        # Max_stops intermediate airports means at most max_stops + 1 flights.
        # If steps is the number of flights taken to reach u, we can take 
        # one more flight if steps < max_stops + 1, which is steps <= max_stops.
        if steps <= max_stops:
            if u in adj:
                for v, p in adj[u]:
                    # Constraint: "visits no airport twice" (no cycles)
                    if v not in path:
                        heapq.heappush(pq, (cost + p, steps + 1, v, path + (v,)))

    return None
