import re

def evaluate(expr: str):
    """
    Evaluates an arithmetic expression following Python's precedence and associativity.
    """
    if not expr.strip():
        raise ValueError("Empty expression")

    # Token pattern covering floats, ints, operators, and parentheses
    token_pattern = re.compile(r'''
        (?P<FLOAT>\d+\.\d*|\.\d+) |
        (?P<INT>\d+) |
        (?P<POW>\*\*) |
        (?P<FLR>//) |
        (?P<MUL>\*) |
        (?P<DIV>/) |
        (?P<MOD>%) |
        (?P<PLUS>\+) |
        (?P<MINUS>-) |
        (?P<LPAREN>\() |
        (?P<RPAREN>\)) |
        (?P<WS>\s+) |
        (?P<ERROR>.)
    ''', re.VERBOSE)

    tokens = []
    for mo in token_pattern.finditer(expr):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'WS':
            continue
        elif kind == 'ERROR':
            raise ValueError(f"Unknown character: {value}")
        elif kind == 'FLOAT':
            tokens.append(('FLOAT', float(value)))
        elif kind == 'INT':
            tokens.append(('INT', int(value)))
        else:
            tokens.append((kind, value))

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else (None, None)

        def consume(self, expected_type=None):
            kind, value = self.peek()
            if kind is None:
                raise ValueError("Unexpected end of expression")
            if expected_type and kind != expected_type:
                raise ValueError(f"Unexpected token {kind}")
            self.pos += 1
            return kind, value

        def parse_expr(self):
            # sum: term ( (PLUS | MINUS) term )*
            node = self.parse_term()
            while True:
                kind, _ = self.peek()
                if kind in ('PLUS', 'MINUS'):
                    self.consume()
                    right = self.parse_term()
                    if kind == 'PLUS': node += right
                    else: node -= right
                else:
                    break
            return node

        def parse_term(self):
            # product: unary ( (MUL | DIV | FLR | MOD) unary )*
            node = self.parse_unary()
            while True:
                kind, _ = self.peek()
                if kind in ('MUL', 'DIV', 'FLR', 'MOD'):
                    self.consume()
                    right = self.parse_unary()
                    if kind == 'MUL':
                        node *= right
                    elif kind == 'DIV':
                        if right == 0: raise ZeroDivisionError()
                        node /= right
                    elif kind == 'FLR':
                        if right == 0: raise ZeroDivisionError()
                        node //= right
                    elif kind == 'MOD':
                        if right == 0: raise ZeroDivisionError()
                        node %= right
                else:
                    break
            return node

        def parse_unary(self):
            # unary: (PLUS | MINUS) unary | power
            kind, _ = self.peek()
            if kind == 'PLUS':
                self.consume()
                return self.parse_unary()
            elif kind == 'MINUS':
                self.consume()
                return -self.parse_unary()
            else:
                return self.parse_power()

        def parse_power(self):
            # power: atom ( POW unary )? (right-associative)
            node = self.parse_atom()
            kind, _ = self.peek()
            if kind == 'POW':
                self.consume()
                right = self.parse_unary()
                node **= right
            return node

        def parse_atom(self):
            # atom: number | ( expr )
            kind, value = self.peek()
            if kind in ('INT', 'FLOAT'):
                self.consume()
                return value
            elif kind == 'LPAREN':
                self.consume()
                node = self.parse_expr()
                if self.peek()[0] != 'RPAREN':
                    raise ValueError("Unbalanced parentheses")
                self.consume('RPAREN')
                return node
            else:
                raise ValueError("Unexpected token")

    parser = Parser(tokens)
    result = parser.parse_expr()
    if parser.pos < len(tokens):
        raise ValueError("Unexpected extra tokens")
    return result
