                    if i < n and line[i] == ',':
                        is_comma = True
                        i += 1

                    fields.append("".join(buf))
                    if is_comma and i == n:
                        fields.append("")
                    break
                else:
                    buf.append(line[i])
                    i += 1
            else:
                if not found_closing:
                    raise ValueError("No closing quote")
        else:
            # --- Unquoted Field ---
            buf = []
            while i < n and line[i] != ',':
                buf.append(line[i])
                i += 1

            fields.append("".join(buf))

            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append("")

