import re

def expand_ranges(s: str) -> list[int]:
    """Parses a comma-separated string of integers and ranges into a sorted list."""
    if not s.strip():
        return []

    items = s.split(',')
    result = set()

    for item in items:
        item = item.strip()
        if not item:
            raise ValueError("Empty item found in list.")

        # Attempt to match the range pattern 'a-b' where a and b are integers
        match = re.fullmatch(r'(-?\d+)-(-?\d+)', item)
        if match:
            a, b = int(match.group(1)), int(match.group(2))
            if a > b:
                raise ValueError(f"Invalid range: {a} > {b}")
            result.update(range(a, b + 1))
        else:
            # If it's not a range, attempt to parse as a single integer
            try:
                result.add(int(item))
            except ValueError:
                raise ValueError(f"Malformed item: '{item}'")

    return sorted(list(result))

def compress_ranges(nums) -> str:
    """Compresses a collection of integers into a string with ranges for consecutive runs."""
    nums = sorted(set(nums))
    if not nums:
        return ""

    # Group consecutive integers into runs
    groups = []
    if nums:
        current_run = [nums[0]]
        for i in range(1, len(nums)):
            if nums[i] == nums[i-1] + 1:
                current_run.append(nums[i])
            else:
                groups.append(current_run)
                current_run = [nums[i]]
        groups.append(current_run)

    # Format each group: 'a-b' for runs of 3+ elements, otherwise single numbers
    parts = []
    for g in groups:
        if len(g) >= 3:
            parts.append(f"{g[0]}-{g[-1]}")
        else:
            for x in g:
                parts.append(str(x))

    return ",".join(parts)
